local RegisteredType = {}
RegisteredType.__index = RegisteredType

function RegisteredType.new(interface, serviceMaker)
	local self = setmetatable({}, RegisteredType)
	self._interface = interface
	self._serviceMaker = serviceMaker
	return self
end

function RegisteredType:AsSingleton()
	self._serviceMaker:AsSingleton()
end

function RegisteredType:PerScope()
	self._serviceMaker:PerScope()
end

return RegisteredType
